-- Read-only pre-check for migration 20261123006861_xray_policies_help on production: one row per passage.
-- old_found or new_found must be true on every row; a row with both false means the page was reworded there,
-- and the migration would stop on it.
select * from (values
  (1, 'help', (select strpos(sections::text, $lw$"In the player (and the mini-player's More), Previously… catches you up on a public-domain book from the second chapter on: the story so far and the last chapter, written by AI from the chapters before yours only."$lw$) > 0 from public.legal_pages where slug = 'help'), (select strpos(sections::text, $lw$To look up a word, select it in the reader and choose Define, or open Dictionary (press D) in the reader or the player and type it. Keep it in My words to review later. The dictionary has English words only for now. Export a book's highlights, notes and journal from the reader's Notes and highlights, or every book's from My Library → Notes.$lw$) > 0 from public.legal_pages where slug = 'help')),
  (2, 'privacy', (select strpos(sections::text, $lw$"Anthropic (Claude) writes book summaries and content notes, answers Ask the book questions, translates passages you select, writes Who's who, chapter quizzes, Previously… recaps and book clubs' discussion questions (see section 6)."$lw$) > 0 from public.legal_pages where slug = 'privacy'), (select strpos(sections::text, $lw$Anthropic (Claude) writes book summaries and content notes, answers Ask the book questions, translates passages you select, writes X-Ray (Who's who, places and terms), chapter quizzes, Previously… recaps and book clubs' discussion questions (see section 6).$lw$) > 0 from public.legal_pages where slug = 'privacy')),
  (3, 'privacy', (select strpos(sections::text, $lw$"Who's who: the characters you've met in a public-domain book so far. We send only the book's text up to your chapter, nothing about you, and keep the list so the next reader at that chapter gets the same one."$lw$) > 0 from public.legal_pages where slug = 'privacy'), (select strpos(sections::text, $lw$X-Ray (Who's who, places and terms): the people, places and terms you've met in a public-domain book so far. We send only the book's text up to your chapter, nothing about you, and keep the names and descriptions so the next reader at that chapter gets the same ones. How often each is mentioned is counted on your device.$lw$) > 0 from public.legal_pages where slug = 'privacy')),
  (4, 'privacy', (select strpos(sections::text, $lw$"Ask the book, Translate, Who's who and book clubs (with their discussion questions) aren't offered to Kids profiles, and natural voices only when a grown-up turns them on for that profile; summaries, content notes, recaps and quizzes are. Summaries, content notes, answers, translations, Who's who, recaps, quizzes and discussion questions are labelled as written by AI, and natural voices are named as Google's in the player."$lw$) > 0 from public.legal_pages where slug = 'privacy'), (select strpos(sections::text, $lw$Ask the book, Translate, X-Ray's AI descriptions and book clubs (with their discussion questions) aren't offered to Kids profiles, and natural voices only when a grown-up turns them on for that profile; summaries, content notes, recaps and quizzes are. Summaries, content notes, answers, translations, X-Ray descriptions, recaps, quizzes and discussion questions are labelled as written by AI, and natural voices are named as Google's in the player.$lw$) > 0 from public.legal_pages where slug = 'privacy')),
  (5, 'childrens-privacy', (select strpos(sections::text, $lw$"They can't write public reading logs, join or start book clubs, follow other readers, share lists by link, upload or import books, search Google Books, ask the book's AI assistant, translate passages or use Who's who."$lw$) > 0 from public.legal_pages where slug = 'childrens-privacy'), (select strpos(sections::text, $lw$They can't write public reading logs, join or start book clubs, follow other readers, share lists by link, upload or import books, search Google Books, ask the book's AI assistant, translate passages or see X-Ray's AI descriptions. Their X-Ray lists the names it finds in the book on the device, with no AI, and sends nothing.$lw$) > 0 from public.legal_pages where slug = 'childrens-privacy')),
  (6, 'terms', (select strpos(sections::text, $lw$"14. Interfere with, disrupt, or create an undue burden on the Services or the networks or services connected to the Services, including by trying to get around the limits on AI summaries, content notes, Ask the book, Translate, Who's who, Previously… recaps, chapter quizzes and discussion questions."$lw$) > 0 from public.legal_pages where slug = 'terms'), (select strpos(sections::text, $lw$14. Interfere with, disrupt, or create an undue burden on the Services or the networks or services connected to the Services, including by trying to get around the limits on AI summaries, content notes, Ask the book, Translate, X-Ray, Previously… recaps, chapter quizzes and discussion questions.$lw$) > 0 from public.legal_pages where slug = 'terms')),
  (7, 'terms', (select strpos(sections::text, $lw$"Summaries, content notes, Ask the book answers, translations, Who's who, Previously… recaps, chapter quizzes and discussion questions are written by AI (Claude) and labelled so. They may be wrong; they're provided for your own reading and may not be republished as LiteraryWorm's."$lw$) > 0 from public.legal_pages where slug = 'terms'), (select strpos(sections::text, $lw$Summaries, content notes, Ask the book answers, translations, X-Ray descriptions, Previously… recaps, chapter quizzes and discussion questions are written by AI (Claude) and labelled so. They may be wrong; they're provided for your own reading and may not be republished as LiteraryWorm's.$lw$) > 0 from public.legal_pages where slug = 'terms')),
  (8, 'acceptable-use', (select strpos(sections::text, $lw$"When you use the AI-powered services provided by LiteraryWorm (\"AI Products\"), you warrant that you will comply with this document, our Legal Terms and all applicable laws and regulations governing AI. Our AI Products are book summaries, content notes, Ask the book, Translate, Who's who, chapter quizzes, Previously… recaps and book clubs' discussion questions. They're written by Claude, an AI model made by Anthropic, and labelled as written by AI."$lw$) > 0 from public.legal_pages where slug = 'acceptable-use'), (select strpos(sections::text, $lw$When you use the AI-powered services provided by LiteraryWorm (\"AI Products\"), you warrant that you will comply with this document, our Legal Terms and all applicable laws and regulations governing AI. Our AI Products are book summaries, content notes, Ask the book, Translate, X-Ray's descriptions (Who's who, places and terms), chapter quizzes, Previously… recaps and book clubs' discussion questions. They're written by Claude, an AI model made by Anthropic, and labelled as written by AI.$lw$) > 0 from public.legal_pages where slug = 'acceptable-use')),
  (9, 'acceptable-use', (select strpos(sections::text, $lw$"That's why everything our AI Products write is labelled as written by AI, and why Ask the book and Who's who are only given the text up to your place in the book, and a quiz only the chapter it's about. A Previously… recap gets only the chapters before yours, and discussion questions only the book up to the end of their chapter. Translate is given only the words you selected, and content notes only the book's details."$lw$) > 0 from public.legal_pages where slug = 'acceptable-use'), (select strpos(sections::text, $lw$That's why everything our AI Products write is labelled as written by AI, and why Ask the book and X-Ray are only given the text up to your place in the book, and a quiz only the chapter it's about. A Previously… recap gets only the chapters before yours, and discussion questions only the book up to the end of their chapter. Translate is given only the words you selected, and content notes only the book's details.$lw$) > 0 from public.legal_pages where slug = 'acceptable-use')),
  (10, 'disclaimer', (select strpos(sections::text, $lw$"Book summaries, content notes, Ask the book answers, translations, Who's who, Previously… recaps, chapter quizzes and discussion questions are written by AI (Claude, made by Anthropic) and labelled as written by AI."$lw$) > 0 from public.legal_pages where slug = 'disclaimer'), (select strpos(sections::text, $lw$Book summaries, content notes, Ask the book answers, translations, X-Ray descriptions, Previously… recaps, chapter quizzes and discussion questions are written by AI (Claude, made by Anthropic) and labelled as written by AI.$lw$) > 0 from public.legal_pages where slug = 'disclaimer')),
  (11, 'status', (select strpos(sections::text, $lw$"Summaries, Ask the book, Who's who and chapter quizzes (AI): working normally."$lw$) > 0 from public.legal_pages where slug = 'status'), (select strpos(sections::text, $lw$Summaries, Ask the book, X-Ray and chapter quizzes (AI): working normally.$lw$) > 0 from public.legal_pages where slug = 'status'))
) as checks(passage, page, old_found, new_found)
order by passage;
